import { Component, OnInit, OnDestroy, NgZone } from '@angular/core';
import { Router } from '@angular/router';
import { NfcData } from '../../../core/models/nfc-data.model';
import { CapacitorNfc, NfcEvent } from '@capgo/capacitor-nfc';
import type { PluginListenerHandle } from '@capacitor/core';

@Component({
  selector: 'app-vehicule-nfc',
  templateUrl: './vehicule-nfc.page.html'
})
export class VehiculeNfcPage implements OnInit, OnDestroy {
  nfcData: NfcData | null = null;
  nfcSupported = false;
  status: 'idle' | 'scanning' | 'writing' | 'success' | 'error' = 'idle';
  errorMsg = '';
  private nfcListener: PluginListenerHandle | null = null;

  constructor(private router: Router, private ngZone: NgZone) {}

  async ngOnInit(): Promise<void> {
    const state = history.state;
    this.nfcData = state?.nfcData ?? null;
    await this.checkNfcSupport();
    if (!this.nfcData) this.router.navigate(['/vehicules']);
  }

  ngOnDestroy(): void {
    this.removeListener();
  }

  private async checkNfcSupport(): Promise<void> {
    try {
      const result = await CapacitorNfc.isSupported();
      this.nfcSupported = result.supported;
    } catch {
      this.nfcSupported = false;
    }
  }

  async startWrite(): Promise<void> {
    console.log('🚀 VehiculeNfcPage startWrite called');
    if (!this.nfcData) return;

    if (!this.nfcSupported) {
      this.status = 'error';
      this.errorMsg = 'NFC non disponible sur cet appareil.';
      return;
    }

    this.status = 'scanning';

    try {
      await this.removeListener();
      console.log('📻 VehiculeNfcPage adding nfcEvent listener');
      this.nfcListener = await CapacitorNfc.addListener('nfcEvent', (event: NfcEvent) => {
        console.log('📡 VehiculeNfcPage nfcEvent received:', event);
        this.ngZone.run(() => this.handleTagDetected(event));
      });

      console.log('🔍 VehiculeNfcPage starting NFC scan');
      await CapacitorNfc.startScanning({
        alertMessage: 'Approchez la carte NFC',
        invalidateAfterFirstRead: false
      });
      console.log('✅ VehiculeNfcPage NFC scan started');
    } catch (err: any) {
      console.error('❌ VehiculeNfcPage error starting scan:', err);
      this.status = 'error';
      this.errorMsg = err?.message ?? 'Erreur lors du démarrage du scan NFC.';
      this.removeListener();
    }
  }

  private async handleTagDetected(event: NfcEvent): Promise<void> {
    console.log('🏷️ VehiculeNfcPage tag detected, handling...');
    try {
      console.log('📄 VehiculeNfcPage preparing records...');
      const records = [this.createTextRecord(this.nfcData!.record1, 'fr')];

      if (this.nfcData?.record2) {
        records.push(this.createTextRecord(this.nfcData.record2, 'fr'));
      }
      console.log('📝 VehiculeNfcPage records ready:', records);

      this.status = 'writing';
      console.log('✍️ VehiculeNfcPage writing to tag...');
      await CapacitorNfc.write({ 
        records, 
        allowFormat: true 
      });
      console.log('✅ VehiculeNfcPage write successful!');
      console.log('🛑 VehiculeNfcPage stopping scan...');
      await CapacitorNfc.stopScanning();
      console.log('🗑️ VehiculeNfcPage removing listener...');
      await this.removeListener();

      this.status = 'success';
    } catch (err: any) {
      console.error('❌ VehiculeNfcPage error writing to tag:', err);
      this.status = 'error';
      this.errorMsg = err?.message ?? 'Erreur lors de l\'écriture NFC.';
      try {
        await CapacitorNfc.stopScanning();
      } catch (stopErr) {
        console.warn('⚠️ VehiculeNfcPage error stopping scan after failure:', stopErr);
      }
      try {
        await this.removeListener();
      } catch (listenerErr) {
        console.warn('⚠️ VehiculeNfcPage error removing listener after failure:', listenerErr);
      }
    }
  }

  private createTextRecord(text: string, languageCode: string = 'fr'): { tnf: number; type: number[]; id: number[]; payload: number[] } {
    const encoder = new TextEncoder();
    const lang = languageCode.trim().toLowerCase().slice(0, 8);
    const langBytes = encoder.encode(lang);
    const textBytes = encoder.encode(text);

    if (langBytes.length > 0x3f) {
      throw new Error('Language code must be at most 63 bytes.');
    }

    const payload = new Uint8Array(1 + langBytes.length + textBytes.length);
    payload[0] = langBytes.length & 0x3f; // UTF-8 encoding with language length
    payload.set(langBytes, 1);
    payload.set(textBytes, 1 + langBytes.length);

    return {
      tnf: 0x01, // Well-known
      type: [0x54], // 'T' for text
      id: [],
      payload: Array.from(payload)
    };
  }

  cancelWrite(): void {
    this.status = 'idle';
  }

  goBack(): void {
    this.removeListener();
    this.router.navigate(['/vehicules']);
  }

  private async removeListener(): Promise<void> {
    if (this.nfcListener) {
      await this.nfcListener.remove();
      this.nfcListener = null;
    }
  }
}
